#!/bin/bash
set -e

# 1) New Invoice now has a 'Visit' dropdown to pick which visit an
#    invoice attaches to (was previously silent/automatic, defaulting
#    to the patient's most recent visit with no way to change it).
# 2) OPD Bill and Surgery Bill printouts now show VISIT ID.
# 3) Surgery Bill's DISCHARGE DATE now always mirrors VISIT DATE,
#    instead of pulling a separately recorded recovery episode date.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/(main)/billing"
echo "" | base64 -d > "app/(main)/billing/actions.js"
echo "Wrote app/(main)/billing/actions.js"

mkdir -p "app/(main)/billing/new"
echo "" | base64 -d > "app/(main)/billing/new/new-invoice-tab.js"
echo "Wrote app/(main)/billing/new/new-invoice-tab.js"

mkdir -p "app/print-templates"
echo "" | base64 -d > "app/print-templates/actions.js"
echo "Wrote app/print-templates/actions.js"

git add "app/(main)/billing/actions.js" "app/(main)/billing/new/new-invoice-tab.js" "app/print-templates/actions.js"
git commit -m "Add visit selector to New Invoice; show Visit ID on bills; fix surgery discharge date"
git push

echo "Done."
